def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find the full-height/full-width non-background divider.
    divider = None
    for c in range(w):
        if grid[0][c] != background and all(grid[r][c] == grid[0][c] for r in range(h)):
            divider = ('v', c, grid[0][c])
            break
    if divider is None:
        for r in range(h):
            if grid[r][0] != background and all(v == grid[r][0] for v in grid[r]):
                divider = ('h', r, grid[r][0])
                break
    if divider is None:
        return out
    axis, pos, divider_color = divider
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != background and grid[r][c] != divider_color]
    if not cells:
        return out
    rmin, rmax = min(r for r, c, v in cells), max(r for r, c, v in cells)
    cmin, cmax = min(c for r, c, v in cells), max(c for r, c, v in cells)
    for r, c, v in cells:
        out[r][c] = background
    if axis == 'v':
        if cmin > pos:
            dc = pos + 1 - cmin
            mark = cmax + dc + 1
        else:
            dc = pos - 1 - cmax
            mark = cmin + dc - 1
        for r, c, v in cells:
            out[r][c + dc] = v
        if 0 <= mark < w:
            for r in range(h):
                out[r][mark] = 8
    else:
        if rmin > pos:
            dr = pos + 1 - rmin
            mark = rmax + dr + 1
        else:
            dr = pos - 1 - rmax
            mark = rmin + dr - 1
        for r, c, v in cells:
            out[r + dr][c] = v
        if 0 <= mark < h:
            out[mark] = [8] * w
    return out
